// Daily Break tests. Builds dist/ (tools/build.sh, the same as the deploy), serves it locally and checks it in
// headless Chromium:
//   layouts  every daily course from LAYOUT_FROM to LAYOUT_TO, plus a few practice seeds, hashed and compared with
//            tests/layouts.json. The holes are generated by simulating shots, so a change to the physics or the
//            generator silently changes everyone's course, today's included. Run `npm run test:update` only when a
//            change is meant to alter layouts, and never for today or any day already played.
//   guide    sweeps the aim across every ball on sample days: whenever the guide lights a pocket, the ball the line
//            follows really drops into it (a perfect strike at some guide pace).
//   fastsim  the guide's early-exit simulation (guidePotsAt) finds exactly the pots a full simulation does.
//   smoke    a first visit: the intro card, "Let's play", one real shot through the pull cue, no errors.
//   trial    the timed trial (?trick): a short run of real shots (perfect strikes at potting aims), each shot's points
//            and multiplier checked against the rules from the table's own record of the shot, the clock only
//            running while aiming, and the run ending with a last shot and points that add up.
// Usage: node tests/run.js [--update] [--only layouts,guide,fastsim,smoke,trial]
const { execFileSync } = require('child_process');
const http = require('http'), fs = require('fs'), path = require('path');
const { chromium } = require('playwright');

const ROOT = path.join(__dirname, '..'), DIST = path.join(ROOT, 'dist'), SNAP = path.join(__dirname, 'layouts.json');
const LAYOUT_FROM = '2026-11-12', LAYOUT_TO = '2027-01-31', PRACTICE = ['practice-a', 'k3v9q', 'Zz1'];
const GUIDE_DAYS = ['2026-11-15', '2026-11-17', '2026-11-24'];
const args = process.argv.slice(2), update = args.includes('--update');
const only = args.includes('--only') ? args[args.indexOf('--only') + 1].split(',') : ['layouts', 'guide', 'fastsim', 'smoke', 'trial'];
const SEEN = { 'dailybreak:seenHelp': '1', 'dailybreak:tappedBall': '1', 'dailybreak:spinDemo': '1' };

const days = (from, to) => { const out = []; for (let d = new Date(from + 'T12:00:00Z'); d <= new Date(to + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + 1)) out.push(d.toISOString().slice(0, 10)); return out; };
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.png': 'image/png', '.webmanifest': 'application/manifest+json', '.json': 'application/json' };
function serve() {
  return new Promise(res => {
    const srv = http.createServer((req, rsp) => {
      let p = decodeURIComponent(new URL(req.url, 'http://x').pathname); if (p.endsWith('/')) p += 'index.html';
      const f = path.join(DIST, path.normalize(p));
      if (!f.startsWith(DIST) || !fs.existsSync(f) || req.method !== 'GET') { rsp.writeHead(404); return rsp.end(); }   // /api/* 404s: nothing reaches production
      rsp.writeHead(200, { 'content-type': types[path.extname(f)] || 'application/octet-stream' }); fs.createReadStream(f).pipe(rsp);
    }).listen(0, '127.0.0.1', () => res(srv));
  });
}
async function page(browser, base, storage, query = '') {
  const p = await browser.newPage({ viewport: { width: 390, height: 844 } });
  p.errors = [];
  p.on('pageerror', e => p.errors.push(e.message));
  p.on('console', m => { if (m.type() === 'error' && !/Failed to load resource|\/api\//.test(m.text())) p.errors.push(m.text()); });
  await p.route(/cloudflareinsights|fonts\.(googleapis|gstatic)/, r => r.abort());   // keep the tests offline and fast
  if (storage) await p.addInitScript(s => { for (const k in s) localStorage.setItem(k, s[k]); }, storage);
  await p.goto(base + '/index.html' + query);
  return p;
}

// FNV-1a over a rounded, function-free JSON of the hole: stable across runs, changes with any real difference
const HASH_JS = `(h => { const j = JSON.stringify(h, (k, v) => typeof v === 'number' ? Math.round(v * 1e4) / 1e4 : typeof v === 'function' ? undefined : v);
  let x = 0x811c9dc5; for (let i = 0; i < j.length; i++) { x ^= j.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; } return x.toString(16).padStart(8, '0'); })`;

const tests = {
  async layouts(browser, base) {
    const p = await page(browser, base, SEEN);
    await p.waitForFunction(() => typeof makeHole === 'function' && typeof HOLES === 'number');
    const seeds = [...days(LAYOUT_FROM, LAYOUT_TO), ...PRACTICE];
    const got = await p.evaluate(([seeds, hashSrc]) => { const hash = eval(hashSrc), out = {};
      for (const s of seeds) out[s] = Array.from({ length: HOLES }, (_, i) => hash(makeHole(s, i))).join(' ');
      return out; }, [seeds, HASH_JS]);
    if (p.errors.length) throw new Error('page errors: ' + p.errors.join(' | '));
    if (update || !fs.existsSync(SNAP)) { fs.writeFileSync(SNAP, JSON.stringify(got, null, 1) + '\n'); return `wrote ${seeds.length} courses to tests/layouts.json`; }
    const want = JSON.parse(fs.readFileSync(SNAP, 'utf8'));
    const changed = seeds.filter(s => want[s] && want[s] !== got[s]), missing = seeds.filter(s => !want[s]);
    if (changed.length) {
      const yesterday = new Date(Date.now() - 864e5).toISOString().slice(0, 10);   // time zones run up to a day behind UTC
      const live = changed.filter(s => /^\d{4}-/.test(s) && s >= yesterday);
      throw new Error(`${changed.length} course(s) changed: ${changed.join(', ')}` + (live.length ? `\n  !! includes today/upcoming days (${live.join(', ')}): players would get a different course than others already played. Gate the change behind a *_FROM date instead.` : '') + '\n  If (and only if) this is intended, run: npm run test:update');
    }
    return `${seeds.length - missing.length} courses unchanged` + (missing.length ? ` (${missing.length} not in the snapshot yet; npm run test:update adds them)` : '');
  },

  async guide(browser, base) {
    const p = await page(browser, base, SEEN);
    await p.waitForFunction(() => typeof phase !== 'undefined' && phase === 'aim');
    const r = await p.evaluate(days => {
      const out = { lit: 0, frames: 0, bad: [] };
      for (const day of days) {
        newRound(day, false);
        for (let hi = 0; hi < HOLES; hi++) {
          startHole(hi); phase = 'aim';
          for (let bi = 0; bi < table.balls.length; bi++) {
            const bb = table.balls[bi], c = table.cue, a0 = Math.atan2(bb.y - c.y, bb.x - c.x);
            for (let d = -4; d <= 4; d += 0.1) {
              aim.angle = a0 + d * Math.PI / 180; draw(performance.now() / 1000, 0); out.frames++;
              if (!guideSim.pks.length) continue;
              out.lit++;
              const P = guideSim.pks[0];
              const real = GUIDE_PACES.some(pw => { const s = simulate(table, aim.angle, pw, aim.spin), b = s.shot.firstHit;
                return b && !s.shot.scratch && s.shot.pots.some(q => q.ball === b && q.pocket === P); });
              if (!real || guideSim.pks.length > 1) out.bad.push(`${day} hole ${hi + 1} ball ${bi} ${d.toFixed(1)}°: lit pocket ${guideSim.pks} but the ball doesn't drop there`);
            }
          }
        }
      }
      return out;
    }, GUIDE_DAYS);
    if (p.errors.length) throw new Error('page errors: ' + p.errors.join(' | '));
    if (!r.lit) throw new Error('the guide never lit a pocket: the sweep is not exercising it');
    if (r.bad.length) throw new Error(`${r.bad.length} lit pocket(s) the ball doesn't drop into:\n  ` + r.bad.slice(0, 10).join('\n  '));
    return `${r.frames} aim angles, ${r.lit} lit, all real pots`;
  },

  async fastsim(browser, base) {
    const p = await page(browser, base, SEEN);
    await p.waitForFunction(() => typeof phase !== 'undefined' && phase === 'aim');
    const r = await p.evaluate(days => {
      let n = 0, pots = 0; const bad = [];
      const full = (a, pw, sp, sd) => { const s = simulate(table, a, pw, sp, null, sd), f = s.shot.firstHit;
        if (s.shot.scratch || !f || (s.shot.kickWalls || 0) > GUIDE_KICK) return [];
        return s.shot.pots.filter(q => q.ball === f && guideWalls(s, q.ball, q.pocket) <= GUIDE_CUSH).map(q => q.pocket); };
      for (const day of days) {
        newRound(day, false);
        for (let hi = 0; hi < HOLES; hi++) {
          startHole(hi); phase = 'aim';
          for (const [sp, sd] of [[0, 0], [0.6, 0], [-0.6, 0], [0, 0.7], [-0.5, -0.7]]) for (let bi = 0; bi < table.balls.length; bi++) {
            const bb = table.balls[bi], c = table.cue, a0 = Math.atan2(bb.y - c.y, bb.x - c.x);
            for (let d = -5; d <= 5; d += 0.37) {
              const a = a0 + d * Math.PI / 180, A = new Set(), B = new Set();
              for (const pw of GUIDE_PACES) { full(a, pw, sp, sd).forEach(i => A.add(i)); guidePotsAt(table, a, pw, sp, GUIDE_KICK, GUIDE_CUSH, sd).forEach(i => B.add(i)); }
              n++; if (A.size) pots++;
              const ka = [...A].sort().join(), kb = [...B].sort().join();
              if (ka !== kb) bad.push(`${day} hole ${hi + 1} ball ${bi} spin ${sp} side ${sd} ${d.toFixed(2)}°: full sim ${ka || 'none'}, fast ${kb || 'none'}`);
            }
          }
        }
      }
      return { n, pots, bad };
    }, GUIDE_DAYS.slice(0, 2));
    if (p.errors.length) throw new Error('page errors: ' + p.errors.join(' | '));
    if (!r.pots) throw new Error('no pots found: the check is not exercising anything');
    if (r.bad.length) throw new Error(`${r.bad.length} aim(s) where the fast guide sim disagrees with the full one:\n  ` + r.bad.slice(0, 10).join('\n  '));
    return `${r.n} aims (${r.pots} with pots) identical to the full simulation`;
  },

  async smoke(browser, base) {
    const p = await page(browser, base, null);   // a first visit: nothing stored
    await p.waitForSelector('#overlay.show [data-close]', { timeout: 10000 });
    await p.click('#overlay.show [data-close]');
    await p.waitForFunction(() => phase === 'aim' && !document.getElementById('overlay').classList.contains('show'));
    const before = await p.evaluate(() => ({ strokes, level: round.level }));
    const box = await p.locator('#pull').boundingBox(), x = box.x + box.width / 2, y = box.y + 20;
    await p.mouse.move(x, y); await p.mouse.down();
    for (let i = 1; i <= 12; i++) { await p.mouse.move(x, y + i * 8); await p.waitForTimeout(30); }
    await p.waitForTimeout(400); await p.mouse.up();
    await p.waitForFunction(b => round.level > b.level || strokes > b.strokes, before, { timeout: 20000 });
    await p.waitForTimeout(1500);
    if (p.errors.length) throw new Error('page errors: ' + p.errors.join(' | '));
    return 'intro, first shot and its result played with no errors';
  },

  async trial(browser, base) {
    const p = await page(browser, base, { ...SEEN, 'dailybreak:firstShot': '1', 'dailybreak:pulled': '1', 'dailybreak:scratchSaved': '1', 'dailybreak:shotLogTip': '1' }, '?trick');
    await p.waitForFunction(() => typeof round !== 'undefined' && round?.trick && phase === 'aim');
    // every strike is perfect, so the shot goes where the test aims; each resolved shot is checked against the rules
    await p.evaluate(() => {
      contact = () => ({ tip: { x: aim.spotX, y: aim.spotY }, quality: 'perfect', off: 0, spin: aim.spin, side: aim.side, power });
      window.__bad = []; window.__shots = 0; window.__movingClock = [];
      const r0 = resolveShot;
      resolveShot = () => {
        const s = table.shot, t = tshot, pts = hs.points, m = hs.mult;
        if (!s || !t) return r0();
        const foul = !s.firstHit || s.scratch, pots = s.pots.filter(q => !q.ball.isCue).length;
        r0();
        window.__shots++;
        const gain = hs.points - pts, round2 = v => Math.round(v * 100) / 100;
        const want = foul || !pots ? 0 : Math.round((100 * pots + t.parts.reduce((a, k) => a + partPts(k), 0)) * (t.gold ? 2 : 1) * m);
        const wantM = foul ? 1 : !pots ? round2(1 + (m - 1) / 2) : round2(m + 0.5 + 0.1 * t.parts.length + (t.gold ? 0.2 : 0));
        if (gain !== want || Math.abs(hs.mult - wantM) > 1e-9) window.__bad.push(`shot ${window.__shots}: +${gain} (want +${want}), x${hs.mult} (want x${wantM}), parts ${t.parts}, gold ${t.gold}, foul ${foul}`);
      };
      trialLeft = 5;
    });
    for (let n = 0; n < 40; n++) {
      if (await p.evaluate(() => round.done)) break;
      await p.waitForFunction(() => round.done || (phase === 'aim' && !banner && !tally), null, { timeout: 30000 });
      if (await p.evaluate(() => round.done)) break;
      await p.waitForTimeout(500);   // some aiming time off the clock
      await p.evaluate(() => {
        const lines = allLines(table).filter(l => !l.blocked);
        let pick = null;
        for (const l of lines) { for (const pw of [0.35, 0.5, 0.25, 0.65]) { const sim = simulate(table, l.angle, pw, 0, null, 0); if (!sim.shot.scratch && sim.shot.pots.length) { pick = { a: l.angle, pw }; break; } } if (pick) break; }
        if (!pick) pick = { a: aim.angle, pw: 0.5 };
        aim.angle = pick.a; power = pick.pw; release();
      });
      // while the balls roll the clock must not move
      const c0 = await p.evaluate(() => trialLeft); await p.waitForTimeout(900);
      const c1 = await p.evaluate(() => [trialLeft, phase]);
      if (c1[1] === 'moving' && c1[0] !== c0) await p.evaluate(([a, b]) => window.__movingClock.push(`${a} -> ${b}`), [c0, c1[0]]);
    }
    await p.waitForFunction(() => round.done, null, { timeout: 30000 });
    const r = await p.evaluate(() => ({ bad: window.__bad, moving: window.__movingClock, shots: window.__shots, last: lastShot, points: round.points, hs: hs.points, logSum: (round.shotLog || []).reduce((a, x) => a + x.total, 0), tables: round.cards.length, share: shareText() }));
    if (p.errors.length) throw new Error('page errors: ' + p.errors.join(' | '));
    if (!r.shots) throw new Error('no shots were played');
    if (r.bad.length) throw new Error(`${r.bad.length} shot(s) scored against the rules:\n  ` + r.bad.join('\n  '));
    if (r.moving.length) throw new Error('the clock ran while the balls rolled: ' + r.moving.join(', '));
    if (!r.last) throw new Error('the run ended without its last shot');
    if (r.points !== r.hs || (r.shots <= 30 && r.logSum !== r.points)) throw new Error(`points don't add up: round ${r.points}, total ${r.hs}, shots ${r.logSum}`);
    if (!/points · \d+ table/.test(r.share)) throw new Error('share text: ' + r.share);
    return `${r.shots} shots, ${r.tables} table(s) cleared, ${r.points.toLocaleString('en-US')} points: every shot scored by the rules, clock stopped while rolling`;
  },
};

(async () => {
  execFileSync(path.join(ROOT, 'tools/build.sh'), { stdio: 'inherit' });
  const srv = await serve(), base = `http://127.0.0.1:${srv.address().port}`, browser = await chromium.launch();
  let failed = 0;
  for (const name of only) {
    const t0 = Date.now();
    try { console.log(`✓ ${name}: ${await tests[name](browser, base)} (${((Date.now() - t0) / 1000).toFixed(1)} s)`); }
    catch (e) { failed++; console.log(`✗ ${name}: ${e.message}`); }
  }
  await browser.close(); srv.close();
  process.exit(failed ? 1 : 0);
})();
